"""build.staged: a project's effect as the compiler sees it - a copy named by where it came from as well as its name.

    python tests/test_stage.py
"""
# AI: below section was generated by an AI
import os
import shutil
import sys
import tempfile

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, ROOT)
import build as B  # noqa: E402
from native import toolchain  # noqa: E402

failed = []


def check(ok, what):
    print(("ok   " if ok else "FAIL ") + what)
    if not ok:
        failed.append(what)


def put(folder, name, text):
    os.makedirs(folder, exist_ok=True)
    p = os.path.join(folder, name)
    open(p, "w", encoding="utf-8", newline="\n").write(text)
    return p


tmp = tempfile.mkdtemp(prefix="stage_")
made = []
try:
    # two projects, each with an effect of the same name: by name alone the second copy wrote over the first
    a = put(os.path.join(tmp, "one"), "Scenes.cpp", "// one\n")
    b = put(os.path.join(tmp, "two"), "Scenes.cpp", "// two\n")
    c = put(os.path.join(tmp, "three"), "scenes.cpp", "// three\n")          # a name that differs only by case
    sa, sb, sc = B.staged(a), B.staged(b), B.staged(c)
    made += [os.path.dirname(s) for s in (sa, sb, sc)]
    check(len({os.path.normcase(s) for s in (sa, sb, sc)}) == 3, "three sources of one name: three copies")
    check([open(s).read() for s in (sa, sb, sc)] == ["// one\n", "// two\n", "// three\n"],
          "each copy is its own source, after the others were staged")
    check([os.path.basename(s) for s in (sa, sb, sc)] == ["Scenes.cpp", "Scenes.cpp", "scenes.cpp"],
          "a copy keeps its file's name (the compiler's errors name it)")
    check(all(os.path.normcase(s).startswith(os.path.normcase(os.path.join(B.paths.BUILD, "stage"))) for s in (sa, sb, sc)),
          "the copies are in build/stage")
    check(len({toolchain._obj_path(s) for s in (sa, sb, sc)}) == 3, "and each has an object of its own")

    # the same source staged again is the same copy, and a change to it is seen
    check(B.staged(a) == sa, "a source staged twice: one copy")
    put(os.path.join(tmp, "one"), "Scenes.cpp", "// one, changed\n")
    check(B.staged(a) == sa and open(sa).read() == "// one, changed\n" and open(sb).read() == "// two\n",
          "a source changed: its copy changed, the other project's not")

    # a source that cannot be read is handed to the compiler as it is
    gone = os.path.join(tmp, "one", "Gone.cpp")
    check(B.staged(gone) == os.path.abspath(gone), "a source that is not there: its own path (the compiler says so)")
finally:
    shutil.rmtree(tmp, ignore_errors=True)
    for d in set(made):
        if os.path.basename(os.path.dirname(d)) == "stage":            # only the folders this test's sources made
            shutil.rmtree(d, ignore_errors=True)

print("FAILED:", failed) if failed else print("all ok")
sys.exit(1 if failed else 0)
